// Post-build: merge agent-discovery headers + Accept:text/markdown rewrites
// into the Build Output API config generated by @astrojs/vercel.
//
// Why: Vercel adapters that use the Build Output API (v3) ignore root
// `vercel.json`. The only way to inject routing/headers is to edit the
// `.vercel/output/config.json` the adapter writes.

import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

const CONFIG_PATH = resolve('.vercel/output/config.json');

const LINK_HEADER_HOME = [
  '</.well-known/api-catalog>; rel="api-catalog"; type="application/linkset+json"',
  '</.well-known/agent-skills/index.json>; rel="https://agentskills.io/rel/skills-index"; type="application/json"',
  '</.well-known/openapi.json>; rel="service-desc"; type="application/vnd.oai.openapi+json;version=3.1"',
  '</resources/>; rel="service-doc"; type="text/html"',
  '</sitemap-index.xml>; rel="sitemap"; type="application/xml"',
].join(', ');

const LINK_HEADER_PAGE = [
  '</.well-known/api-catalog>; rel="api-catalog"; type="application/linkset+json"',
  '</.well-known/agent-skills/index.json>; rel="https://agentskills.io/rel/skills-index"; type="application/json"',
].join(', ');

function linkAltMd(slug) {
  return `</md/${slug}.md>; rel="alternate"; type="text/markdown"`;
}

// Routes injected BEFORE the filesystem handle — they either add headers
// and continue, or rewrite to the markdown variant for Accept: text/markdown.
const INJECT_PRE_FS = [
  // Accept: text/markdown content negotiation for HTML pages
  {
    src: '^/$',
    has: [{ type: 'header', key: 'accept', value: '.*text/markdown.*' }],
    dest: '/md/index.md',
  },
  {
    src: '^/resources/?$',
    has: [{ type: 'header', key: 'accept', value: '.*text/markdown.*' }],
    dest: '/md/resources.md',
  },
  {
    src: '^/about/?$',
    has: [{ type: 'header', key: 'accept', value: '.*text/markdown.*' }],
    dest: '/md/about.md',
  },
  {
    src: '^/token-usage/?$',
    has: [{ type: 'header', key: 'accept', value: '.*text/markdown.*' }],
    dest: '/md/token-usage.md',
  },

  // Link: response headers on canonical HTML pages (continue through)
  {
    src: '^/$',
    headers: {
      Link: `${LINK_HEADER_HOME}, ${linkAltMd('index')}`,
      Vary: 'Accept',
    },
    continue: true,
  },
  {
    src: '^/resources/?$',
    headers: {
      Link: `${LINK_HEADER_PAGE}, ${linkAltMd('resources')}`,
      Vary: 'Accept',
    },
    continue: true,
  },
  {
    src: '^/about/?$',
    headers: {
      Link: `${LINK_HEADER_PAGE}, ${linkAltMd('about')}`,
      Vary: 'Accept',
    },
    continue: true,
  },
  {
    src: '^/token-usage/?$',
    headers: {
      Link: `${LINK_HEADER_PAGE}, ${linkAltMd('token-usage')}`,
      Vary: 'Accept',
    },
    continue: true,
  },
];

// Routes injected AFTER the filesystem handle — Content-Type overrides for
// files that Vercel's static server serves with the wrong MIME.
const INJECT_POST_FS = [
  {
    src: '^/\\.well-known/api-catalog$',
    headers: {
      'Content-Type': 'application/linkset+json',
      'Cache-Control': 'public, max-age=3600',
    },
    continue: true,
  },
  {
    src: '^/\\.well-known/openapi\\.json$',
    headers: {
      'Content-Type': 'application/vnd.oai.openapi+json;version=3.1',
      'Cache-Control': 'public, max-age=3600',
    },
    continue: true,
  },
  {
    src: '^/\\.well-known/agent-skills/index\\.json$',
    headers: {
      'Content-Type': 'application/json',
      'Cache-Control': 'public, max-age=3600',
    },
    continue: true,
  },
  {
    src: '^/\\.well-known/agent-skills/skills/[^/]+/SKILL\\.md$',
    headers: {
      'Content-Type': 'text/markdown; charset=utf-8',
      'Cache-Control': 'public, max-age=3600',
    },
    continue: true,
  },
  {
    src: '^/md/[^/]+\\.md$',
    headers: {
      'Content-Type': 'text/markdown; charset=utf-8',
      'Cache-Control': 'public, max-age=600',
      Vary: 'Accept',
    },
    continue: true,
  },
];

async function main() {
  const raw = await readFile(CONFIG_PATH, 'utf8');
  const config = JSON.parse(raw);
  if (!Array.isArray(config.routes)) {
    throw new Error(`Unexpected config: routes missing in ${CONFIG_PATH}`);
  }

  const routes = config.routes;
  const fsIdx = routes.findIndex((r) => r && r.handle === 'filesystem');
  if (fsIdx === -1) {
    throw new Error('Could not find filesystem handle in routes');
  }

  // Idempotency: remove any previous injections
  const marker = (r) =>
    r && (
      (r.headers && typeof r.headers.Link === 'string' && r.headers.Link.includes('api-catalog')) ||
      (r.dest && typeof r.dest === 'string' && r.dest.startsWith('/md/') && r.dest.endsWith('.md')) ||
      (r.headers && r.headers['Content-Type'] === 'application/linkset+json') ||
      (r.headers && typeof r.headers['Content-Type'] === 'string' && r.headers['Content-Type'].includes('openapi')) ||
      (r.src && (r.src.includes('agent-skills') || r.src.includes('^/md/')))
    );
  config.routes = routes.filter((r) => !marker(r));

  const rebuiltFsIdx = config.routes.findIndex((r) => r && r.handle === 'filesystem');
  config.routes.splice(rebuiltFsIdx, 0, ...INJECT_PRE_FS);

  const postFsIdx = config.routes.findIndex((r) => r && r.handle === 'filesystem') + 1;
  config.routes.splice(postFsIdx, 0, ...INJECT_POST_FS);

  await writeFile(CONFIG_PATH, JSON.stringify(config, null, '\t') + '\n', 'utf8');
  console.log(
    `[inject-vercel-config] patched ${CONFIG_PATH}: +${INJECT_PRE_FS.length} pre-fs routes, +${INJECT_POST_FS.length} post-fs routes`
  );
}

main().catch((err) => {
  console.error('[inject-vercel-config] failed:', err);
  process.exit(1);
});
